  "summary": "KTP把虚构实体的属性只放在生成训练图像中，从caption移除答案，再用无输入图像的纯文本QA测知识转移。跨三类UMM，视觉可生成性与语言可调用性之间仍有差距；部分实体的交错图文对齐能改善其他未接受QA监督实体的知识访问。",
