  "objective": "保留各模型原T2I目标，增加实体子集的text QA或交错图文监督；不提出新的forward corruption或clean/noise/velocity目标。",
  "decoding": "测试主体为一次纯文本QA，不插入生成图像；visual accessibility另走各自原生成器。训练步数、NFE、AR初始化和显存须按底座分别核算，不是等预算生成器排名。",
