  "summary": "以固定Leech lattice视觉词表建模raster图像，以显式程序表达SVG/网页/文档，再用harness规划、候选选择与局部修复。必须拆开tokenizer、单次AR生成与agentic harness；论文报告的系统提升不等于生成器本身提升。",
