  "experiment": "固定LLM主干、离散codec、数据、参数与训练FLOPs，对比AR、masked token恢复与metric-path解码；先保持token标签和head相同，再独立改变共享方式。报OCRBench/DocVQA/TextVQA、生成文字OCR、GenEval、code coverage、邻接共现、采样调用、吞吐/显存/稳定性；若换codec先测重建上限。",
