const PAGE_SIZE = 10;
type Language = "en" | "zh";

type EnglishPaperCopy = {
  summary: string;
  why: string;
  inspiration: string;
  experiment: string;
  state: string;
  objective: string;
  decoding: string;
  sharing: string;
  open: string;
  action?: string;
  rollout?: string;
  evaluation?: string;
};

function inferDomain(paper: Paper): NonNullable<Paper["domain"]> {
  if (paper.domain) return paper.domain;
  if (paper.category === "世界模型") return "World Model";
  if (["统一多模态", "统一视觉 Token"].includes(paper.category)) return "UMM";
  if (paper.category === "可解释性") return "可解释性";
  if (paper.category === "评测诊断") return "评测诊断";
  const text = [paper.title, paper.paradigm, paper.summary, paper.state, paper.decoding].join(" ");
  if (/video|视频|多帧|时序|temporal|stream|4d|future frame|未来帧/i.test(text)) return "视频生成";
  if (paper.category === "多帧推理") return "视频生成";
  return "图像生成";
}

const englishLabels: Record<string, string> = {
  "今日精选": "Today's Picks",
  "全部内容": "All Resources",
  "精读清单": "Deep Reads",
  "借鉴优先": "Experiment Ideas",
  "已保存": "Saved Reads",
  "离散 UMM": "Discrete UMM",
  "图像生成": "Image Generation",
  "视频生成": "Video Generation",
  "可解释性": "Interpretability",
  "评测诊断": "Evaluation & Diagnostics",
};

function displayLabel(value: string, language: Language) {
  return language === "en" ? (englishLabels[value] ?? value) : value;
}

function englishDomain(paper: Paper) {
  return displayLabel(inferDomain(paper), "en");
}

